export function ThemeToggle() {
  const { theme, setTheme } = useTheme()
  const [mounted, setMounted] = useState(false)
  const { radius, setRadius, syncRadiusFromBody } = useThemeRadius()

  useEffect(() => {
    setTimeout(() => setMounted(true), 0)
  }, [])

  useEffect(() => {
    if (mounted) {
      // Restore saved preset class from localStorage on mount
      const savedPreset = localStorage.getItem(THEME_PRESET_KEY)
      const body = document.body
      themeClasses.forEach((cls) => body.classList.remove(cls))

      if (savedPreset && savedPreset !== "default") {
        body.classList.add(savedPreset)
      } else {
        body.classList.add("default")
      }

      // Only sync radius from CSS if there's no saved radius preference
      // (syncRadiusFromBody removes inline --radius which causes a flash)
      if (!localStorage.getItem("theme-radius")) {
        syncRadiusFromBody()
      }
    }
  }, [mounted, syncRadiusFromBody])

  const toggleBodyClass = useCallback(
    (className: string) => {
      const body = document.body
      const isCurrentlyActive = body.classList.contains(className)

      themeClasses.forEach((cls) => body.classList.remove(cls))

      if (!isCurrentlyActive) {
        body.classList.add(className)
        localStorage.setItem(THEME_PRESET_KEY, className)
      } else {
        localStorage.removeItem(THEME_PRESET_KEY)
      }

      syncRadiusFromBody()
    },
    [syncRadiusFromBody]
  )

  const handleThemeChange = useCallback(
    (newTheme: string, event: MouseEvent<HTMLButtonElement>) => {
      if (theme === newTheme) return

      const doc = document as any
      if (
        typeof window === "undefined" ||
        !doc.startViewTransition ||
        window.matchMedia("(prefers-reduced-motion: reduce)").matches
      ) {
        setTheme(newTheme)
        return
      }

      const x = event.clientX
      const y = event.clientY
      const endRadius = Math.hypot(
        Math.max(x, window.innerWidth - x),
        Math.max(y, window.innerHeight - y)
      )

      const transition = doc.startViewTransition(() => {
        setTheme(newTheme)
      })

      transition.ready.then(() => {
        document.documentElement.animate(
          {
            clipPath: [
              `circle(0px at ${x}px ${y}px)`,
              `circle(${endRadius}px at ${x}px ${y}px)`,
            ],
          },
          {
            duration: 500,
            easing: "ease-in-out",
            pseudoElement: "::view-transition-new(root)",
          }
        )
      })
    },
    [theme, setTheme]
  )

  const handlePresetChange = useCallback(
    (presetClass: string, event: MouseEvent<HTMLButtonElement>) => {
      const doc = document as any
      if (
        typeof window === "undefined" ||
        !doc.startViewTransition ||
        window.matchMedia("(prefers-reduced-motion: reduce)").matches
      ) {
        toggleBodyClass(presetClass)
        return
      }

      const x = event.clientX
      const y = event.clientY
      const endRadius = Math.hypot(
        Math.max(x, window.innerWidth - x),
        Math.max(y, window.innerHeight - y)
      )

      const transition = doc.startViewTransition(() => {
        toggleBodyClass(presetClass)
      })

      transition.ready.then(() => {
        document.documentElement.animate(
          {
            clipPath: [
              `circle(0px at ${x}px ${y}px)`,
              `circle(${endRadius}px at ${x}px ${y}px)`,
            ],
          },
          {
            duration: 500,
            easing: "ease-in-out",
            pseudoElement: "::view-transition-new(root)",
          }
        )
      })
    },
    [toggleBodyClass]
  )

  const resetDefault = useCallback(() => {
    setTheme("light")
    themeClasses.forEach((cls) => document.body.classList.remove(cls))
    document.body.classList.add("default")
    localStorage.removeItem(THEME_PRESET_KEY)
    localStorage.removeItem("theme-radius")
    document.body.style.removeProperty("--radius")
    syncRadiusFromBody()
  }, [setTheme, syncRadiusFromBody])

  if (!mounted) {
    return (
      <div className="h-9 w-9 rounded-lg border border-transparent bg-muted/50" />
    )
  }

  return (
    <>
      <ThemePresetStyles />
      <Sheet modal={true}>
        <SheetTrigger
          render={
            <Button
              variant="ghost"
              size="icon"
              aria-label="Theme Customizer"
              className="relative h-9.5 w-9.5 overflow-hidden rounded-full p-[2px] hover:opacity-90"
            >
              <div className="absolute inset-0 animate-[spin_3s_linear_infinite] bg-[linear-gradient(239.74deg,#C800DE_0%,#9810FA_16.93%,#4680FF_29.63%,#D08700_55.02%,#FF6900_67.72%,#FB2C36_84.65%)]" />
              <div className="relative z-10 flex h-full w-full items-center justify-center rounded-full bg-foreground dark:bg-white">
                <Settings2 className="size-4.5 text-background" />
              </div>
            </Button>
          }
        >
          Open Sheet
        </SheetTrigger>
        <SheetContent className="data-[side=right]:sm:max-w-80 [&~[data-slot='sheet-overlay']]:hidden">
          <SheetHeader>
            <SheetTitle>Settings</SheetTitle>
          </SheetHeader>
          <div className="no-scrollbar overflow-y-auto px-5">
            <div className="flex flex-col gap-6">
              <div className="flex flex-col gap-1">
                <h6>Theme Mode</h6>
                <p className="text-foreground">
                  Choose light, dark, or system mode
                </p>
              </div>
              <div className="grid grid-cols-3 gap-2">
                <Button
                  onClick={(e) => handleThemeChange("light", e)}
                  className="inline-flex flex-col items-center justify-center gap-1 py-4"
                  aria-label="Toggle Theme"
                  variant={theme === "light" ? "default" : "outline"}
                >
                  <Sun className="size-6" />
                  Light
                </Button>
                <Button
                  onClick={(e) => handleThemeChange("dark", e)}
                  className="inline-flex flex-col items-center justify-center gap-1 py-4"
                  aria-label="Toggle Theme"
                  variant={theme === "dark" ? "default" : "outline"}
                >
                  <Moon className="size-6" />
                  Dark
