import { formatStarCount } from "@/utils/github"

//  ------------------------------ | HOOK - USE GITHUB STAR COUNT | ------------------------------  //

const GITHUB_STARS_FALLBACK = "122"

export function useGithubStarCount() {
  const [stars, setStars] = useState(GITHUB_STARS_FALLBACK)

  useEffect(() => {
    const controller = new AbortController()

    fetch("/api/github-stars", {
      signal: controller.signal,
      cache: "no-store",
    })
      .then((res) => (res.ok ? res.json() : Promise.reject(res)))
      .then((data: { count: number | null }) => {
        if (typeof data.count === "number") {
          setStars(formatStarCount(data.count))
        }
      })
      .catch(() => {
        // Keep the fallback count if the live count can't be fetched.
      })

    return () => controller.abort()
  }, [])

  return stars
}

"use client"

import { useCallback, useEffect, useState } from "react"

const parseCssRadius = (value: string) => {
  const normalized = value.trim().toLowerCase()
  if (!normalized) return NaN
  if (normalized.endsWith("rem")) return parseFloat(normalized)
  if (normalized.endsWith("px")) {
    const px = parseFloat(normalized)
    const rootFontSize =
      parseFloat(getComputedStyle(document.documentElement).fontSize) || 16
    return px / rootFontSize
  }
  return parseFloat(normalized)
}

const getCssRootRadius = () => {
  if (typeof window === "undefined") return null
  const cssRadius = getComputedStyle(document.documentElement).getPropertyValue(
    "--radius"
  )
  const parsedRadius = parseCssRadius(cssRadius)
  return Number.isNaN(parsedRadius) ? null : parsedRadius
}

//  ------------------------------ | CUSTOMIZER - USE THEME RADIUS | ------------------------------  //

export function useThemeRadius() {
  const [radius, setRadius] = useState<number>(() => {
    if (typeof window === "undefined") return 0.3
    return getCssRootRadius() ?? 0.3
  })

  const syncRadiusFromBody = useCallback(() => {
    const body = document.body
    body.style.removeProperty("--radius")

    const cssRadius = getComputedStyle(body).getPropertyValue("--radius")
    const nextRadius = parseCssRadius(cssRadius)

    if (!Number.isNaN(nextRadius)) {
      setRadius(nextRadius)
    }
  }, [])

  useEffect(() => {
    document.body.style.setProperty("--radius", `${radius}rem`)
  }, [radius])

  return { radius, setRadius, syncRadiusFromBody }
}

//  ------------------------------ | UTILS - GITHUB | ------------------------------  //

const GITHUB_STARGAZERS_COUNT_URL =
  "https://api.github.com/repos/codedthemes/uiable/stargazers/count"

export async function fetchGithubStarCount(): Promise<number | null> {
  try {
    const res = await fetch(GITHUB_STARGAZERS_COUNT_URL, {
      next: { revalidate: 3600 },
    })
    if (!res.ok) return null

    const data = (await res.json()) as { count: number }
    return typeof data.count === "number" ? data.count : null
  } catch (error) {
    console.error("[github] Failed to fetch star count:", error)
    return null
  }
}

export function formatStarCount(count: number): string {
  return new Intl.NumberFormat("en-US", { notation: "compact" }).format(count)
}
